'use strict';
const {test,expect}=require('../workspace-paired-observation.cjs');
const fs=require('node:fs/promises'),crypto=require('node:crypto');
const start=require('../../helpers/financialLifecycleBrowserServer');
let server;
// Reviewed composite successors retain180s callback and15s assertions; native
// actions use a stricter15s bound so an absent control cannot consume the callback.
test.use({actionTimeout:15000});
test.beforeAll(async()=>{test.setTimeout(240000);server=await start({port:0,includeSyntheticDownloads:true,includeSyntheticPersonalDownloads:true});});
test.beforeEach(async()=>server.reset());
test.afterAll(async()=>server?.close());
const pdf=require('node:fs').readFileSync(require('node:path').join(__dirname,'fixtures/paralegal-valid.pdf')),replacementPdf=require('node:fs').readFileSync(require('node:path').join(__dirname,'fixtures/paralegal-valid-replacement.pdf')); 
const userFields=['_id','role','status','firstName','lastName','state','location','bio','about','practiceAreas','specialties','skills','stateExperience','jurisdictions','yearsExperience','resumeURL','certificateURL','writingSampleURL','profileImage','avatarURL','profileImageKey','profileImageOriginalKey','pendingProfileImage','pendingProfileImageKey','pendingProfileImageOriginalKey','profilePhotoStatus','profilePhotoRevision','preferences','availability','availabilityDetails','onboarding'];
async function userRecord(id){const User=require('../../../models/User'),u=await User.collection.findOne({_id:new(require('mongoose').Types.ObjectId)(id)});return Object.fromEntries(userFields.map(k=>[k,u[k]]));}
async function business(){const mongoose=require('mongoose');return Object.fromEntries(await Promise.all(['Case','Job','Application','CaseFile','Message','Payout','PaymentOperation','PlatformIncome'].map(async n=>[n,await mongoose.models[n].collection.find({}).sort({_id:1}).toArray()])));}
async function person(browser,role,width,publicProfile=false){const actor=await server.createUser(role,{},publicProfile),context=await browser.newContext({viewport:{width,height:1000}});await context.addCookies([actor.cookie]);await context.route('**/*',route=>new URL(route.request().url()).origin===server.origin?route.continue():route.abort());return {...actor,context,page:await context.newPage()};}
async function api(actor,method,path,data,status=200){const request=actor.context.request,csrf=await(await request.get(server.origin+'/api/csrf')).json();const response=await request[method](server.origin+path,{headers:{'X-CSRF-Token':csrf.csrfToken},...(data?{data}: {})});expect(response.headers()['x-lpc-test-server']).toBe('financial-lifecycle-browser');expect(response.status(),`${method} ${path}: ${await response.text()}`).toBe(status);return response.json();}
async function openSettings(actor,width,tab='profile'){await actor.page.goto(server.origin+'/paralegal-v2.html#/home');await expect(actor.page.locator('body')).toHaveAttribute('data-v2-session','ready');if(width<800)await actor.page.locator('[data-v2-mobile-menu]').click();await actor.page.getByRole('button',{name:'Open profile menu',exact:true}).click();await actor.page.getByRole('menuitem',{name:'Profile Settings',exact:true}).click();if(tab!=='profile')await actor.page.getByRole('tab',{name:tab,exact:true}).click();}
async function image(page){return Buffer.from(await page.evaluate(()=>{const c=document.createElement('canvas');c.width=64;c.height=64;const x=c.getContext('2d');x.fillStyle='#6495ed';x.fillRect(0,0,64,64);x.fillStyle='#222';x.fillRect(20,20,24,24);return c.toDataURL('image/png').split(',')[1];}),'base64');}
async function exportEvidence(info,value){await fs.writeFile(info.outputPath('paralegal-local-evidence.json'),JSON.stringify({...value,requests:server.evidence().requests,storage:server.evidence().external.storage,mailSubjects:server.evidence().external.mail.map(x=>x[1]),providerCalls:server.evidence().provider,syntheticProviderOnly:true},null,2));}

