async function multipart(actor,path,body,status=200){const req=actor.context.request,csrf=await(await req.get(server.origin+'/api/csrf')).json();const response=await req.post(server.origin+path,{headers:{'X-CSRF-Token':csrf.csrfToken},multipart:body});expect(response.status(),`${path}: ${await response.text()}`).toBe(status);return response.json();}
async function readyProfile(actor,admin){const User=require('../../../models/User');await User.updateOne({_id:actor.id},{$set:{profileImage:'',avatarURL:'',resumeURL:'',bio:'Actual synthetic litigation and filing profile.',skills:['Legal research'],profilePhotoStatus:'unsubmitted',preferences:{hideProfile:true,theme:'light'}}});const bytes=await image(actor.page);let me=await api(actor,'get','/api/users/me');await multipart(actor,'/api/uploads/paralegal-resume',{file:{name:'Resume.pdf',mimeType:'application/pdf',buffer:pdf},expectedOwnerId:actor.id,expectedDocumentKey:''});await multipart(actor,'/api/uploads/profile-photo',{file:{name:'profile.png',mimeType:'image/png',buffer:bytes},original:{name:'original.png',mimeType:'image/png',buffer:bytes},expectedOwnerId:actor.id,expectedPhotoRevision:me.profilePhotoRevision});await api(admin,'post',`/api/admin/profile-photos/${actor.id}/approve`,{});return userRecord(actor.id);}
async function postMatter(attorney,title,options={}){const value=await api(attorney,'post','/api/cases',{title,practiceArea:'immigration',state:'CA',totalAmount:400,experience:'5+ years',deadline:'2027-03-14',description:'Prepare the actual synthetic exhibit index and verify supporting records.',tasks:[{title:'Prepare exhibit index'},{title:'Check record dates'}],...options},201);return {id:String(value._id||value.id||value.case?._id),jobId:String(value.jobId),value};}
async function filter(page,label,value){const button=page.getByRole('button',{name:/^Filters/}),panel=page.locator('.v2-browse-filter');await button.click();await panel.getByRole('combobox',{name:label,exact:true}).selectOption(value);await expect(panel).not.toBeVisible();await expect(button).toBeFocused();await expect(page.locator('[data-v2-route-outlet]')).not.toHaveAttribute('aria-busy','true');}
async function storedApplication(caseId,actorId){const Application=require('../../../models/Application'),Job=require('../../../models/Job'),Case=require('../../../models/Case'),job=await Job.findOne({caseId}).lean();return {application:await Application.findOne({jobId:job._id,paralegalId:actorId}).lean(),job,case:await Case.findById(caseId).lean()};}
async function applyNative(page,title,note){const row=page.getByRole('heading',{name:title,exact:true}).locator('xpath=ancestor::article');await row.getByRole('button',{name:'Apply',exact:true}).click();const dialog=page.getByRole('dialog',{name:`Apply to ${title}`,exact:true});await dialog.getByRole('textbox',{name:'Cover letter',exact:true}).fill(note);return dialog;}

