  await page.route('**/api/paralegals/update-availability',async route=>{availabilityWrites++;if(failAvailability){await new Promise(resolve=>{releaseAvailability=resolve;});return route.fulfill({status:503,contentType:'application/json',body:JSON.stringify({error:'Synthetic availability temporarily unavailable.'})});}return route.continue();});
  await trigger.click();await dialog.getByRole('radio',{name:'Not available',exact:true}).check();await dialog.getByLabel('Available again',{exact:true}).fill(tomorrow);await dialog.getByRole('button',{name:'Cancel',exact:true}).click();expect(await userRecord(actor.id)).toEqual(before);expect(availabilityWrites).toBe(0);await expect(trigger).toBeFocused();
  await trigger.click();await dialog.getByRole('radio',{name:'Not available',exact:true}).check();await dialog.getByLabel('Available again',{exact:true}).fill(past);await dialog.getByRole('button',{name:'Save availability',exact:true}).click();expect(availabilityWrites).toBe(0);expect(await dialog.locator('form').evaluate(form=>form.checkValidity())).toBe(false);await dialog.getByLabel('Available again',{exact:true}).fill(tomorrow);
  await dialog.getByRole('button',{name:'Save availability',exact:true}).click();await expect.poll(()=>availabilityWrites).toBe(1);await expect(dialog.getByRole('button',{name:'Save availability',exact:true})).toBeDisabled();await page.keyboard.press('Escape');await expect(dialog).toBeVisible();releaseAvailability();await expect(dialog.getByRole('alert')).toContainText('temporarily unavailable');expect(await userRecord(actor.id)).toEqual(before);await expect(dialog.getByLabel('Available again',{exact:true})).toHaveValue(tomorrow);failAvailability=false;
  await dialog.getByRole('button',{name:'Save availability',exact:true}).click();await expect(dialog).toHaveCount(0);expect(availabilityWrites).toBe(2);expect((await userRecord(actor.id)).availabilityDetails.status).toBe('unavailable');await other.bringToFront();await expect(otherTrigger).toContainText('Not available');
  await page.bringToFront();await expect(trigger).toBeEnabled();await trigger.click();await dialog.getByRole('radio',{name:'Available now',exact:true}).check();await dialog.getByRole('button',{name:'Save availability',exact:true}).click();await expect(dialog).toHaveCount(0);expect((await userRecord(actor.id)).availabilityDetails.nextAvailable).toBeNull();expect(availabilityWrites).toBe(3);await page.reload();await expect(trigger).toContainText('Available now');await other.close();steps.push({branch:'availability',cancelConserved:true,pastDateRejectedWithoutWrite:true,singleFlight:true,failureConserved:true,retryPersisted:true,otherHomeRefreshed:true,availableClearsHiddenDate:true,writes:availabilityWrites});
  await openSettings(actor,width,'Preferences');const hide=page.getByRole('checkbox',{name:'Hide profile',exact:true});await expect(hide).toBeEnabled();await expect(hide).not.toBeChecked();
  const publicBefore=await actor.context.request.get(server.origin+`/api/public/paralegals/${actor.id}`);expect(publicBefore.status()).toBe(200);
  await hide.check();await expect.poll(async()=>(await userRecord(actor.id)).preferences.hideProfile).toBe(true);await expect(page.locator('[data-preference-status]')).toContainText('Profile visibility saved');const hidden=await actor.context.request.get(server.origin+`/api/public/paralegals/${actor.id}`);expect(hidden.status()).toBe(404);await page.reload();await expect(hide).toBeChecked();
