async function invitationRecord(id){return require('../../../models/Case').findById(id).lean();}
async function requestRequirements(attorney,id,paraId,details,first=false){const data={expectedOwnerId:attorney.id,conflictsCheckRequired:'true',conflictsDetails:details,confidentialityAgreementRequired:'true'};if(first)data.confidentialityFile={name:'Confidentiality.pdf',mimeType:'application/pdf',buffer:pdf};return multipart(attorney,`/api/cases/${id}/pre-engagement/${paraId}/request`,data);}
